import{_ as t,c as a,o,ag as r}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Welcome","description":"","frontmatter":{"title":"Welcome"},"headers":[],"relativePath":"community/welcome.md","filePath":"community/welcome.md","lastUpdated":null}'),i={name:"community/welcome.md"};function n(s,e,h,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h1><h2 id="the-irregularchat-community-of-interest-coi" tabindex="-1">The IrregularChat Community of Interest (CoI) <a class="header-anchor" href="#the-irregularchat-community-of-interest-coi" aria-label="Permalink to &quot;The IrregularChat Community of Interest (CoI)&quot;">​</a></h2><p>Welcome to the Community! Now that you are logged in, you’ll have access to the full wiki and other services!</p><p>You&#39;ve just joined a community focused on breaking down silos, fostering innovation, and supporting service members and veterans.</p><p>You can find those services and all the different chats listed on the <a href="/general/links.html">Services and Chats Page</a></p><p>The same logic that got you here will work to log you into those other services. So you may want to bookmark: <a href="https://sso.irregularchat.com" target="_blank" rel="noreferrer">https://sso.irregularchat.com</a> as it has bookmarks to IrregularChat Services</p><h3 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h3><h3 id="the-irregularchat-login" tabindex="-1">The IrregularChat Login <a class="header-anchor" href="#the-irregularchat-login" aria-label="Permalink to &quot;The IrregularChat Login&quot;">​</a></h3><p><strong>CHANGE YOUR PASSWORD</strong> Then change your password AND email here: <a href="http://url.irregular.chat/change-password" target="_blank" rel="noreferrer">http://url.irregular.chat/change-password</a></p><p>You also have the option to update your signal-referenced name, email, and username. Bookmark this and test out the services. “KASAM” is not intended to run on mobile browsers, but all these services can be accessed on NIPR or personal web browsers.</p><h3 id="📜-rules-of-engagement" tabindex="-1">📜 Rules of Engagement <a class="header-anchor" href="#📜-rules-of-engagement" aria-label="Permalink to &quot;📜 Rules of Engagement&quot;">​</a></h3><h2 id="respect-all-members-don-t-be-disrespectful" tabindex="-1">Respect all members. Don&#39;t be disrespectful. <a class="header-anchor" href="#respect-all-members-don-t-be-disrespectful" aria-label="Permalink to &quot;Respect all members. Don&#39;t be disrespectful.&quot;">​</a></h2><h2 id="leave-your-rank-and-ego-at-the-door" tabindex="-1">Leave your rank and ego at the door. <a class="header-anchor" href="#leave-your-rank-and-ego-at-the-door" aria-label="Permalink to &quot;Leave your rank and ego at the door.&quot;">​</a></h2><h2 id="stay-on-topic-to-maintain-focus" tabindex="-1">Stay on topic to maintain focus. <a class="header-anchor" href="#stay-on-topic-to-maintain-focus" aria-label="Permalink to &quot;Stay on topic to maintain focus.&quot;">​</a></h2><h2 id="no-sharing-of-confidential-personally-identifiable-information-pii-or-classified-information-encryption-does-not-make-it-permissible" tabindex="-1">No sharing of confidential, personally identifiable information (PII), or classified information. Encryption does not make it permissible. <a class="header-anchor" href="#no-sharing-of-confidential-personally-identifiable-information-pii-or-classified-information-encryption-does-not-make-it-permissible" aria-label="Permalink to &quot;No sharing of confidential, personally identifiable information (PII), or classified information. Encryption does not make it permissible.&quot;">​</a></h2><h3 id="share-content-using-the-appropriate-levels-and-direct-users-to-relevant-content-locations" tabindex="-1">Share content using the appropriate levels and direct users to relevant content locations. <a class="header-anchor" href="#share-content-using-the-appropriate-levels-and-direct-users-to-relevant-content-locations" aria-label="Permalink to &quot;Share content using the appropriate levels and direct users to relevant content locations.&quot;">​</a></h3><h2 id="engage-with-the-wiki" tabindex="-1">Engage with the Wiki: <a class="header-anchor" href="#engage-with-the-wiki" aria-label="Permalink to &quot;Engage with the Wiki:&quot;">​</a></h2><h3 id="utilize-the-wiki-for-resources-if-you-find-gaps-fill-them-out-and-share-them-in-the-chat" tabindex="-1">Utilize the wiki for resources. If you find gaps, fill them out and share them in the chat. <a class="header-anchor" href="#utilize-the-wiki-for-resources-if-you-find-gaps-fill-them-out-and-share-them-in-the-chat" aria-label="Permalink to &quot;Utilize the wiki for resources. If you find gaps, fill them out and share them in the chat.&quot;">​</a></h3><h3 id="notice-inaccuracies-or-missing-information-lead-the-effort-to-correct-and-enhance-it" tabindex="-1">Notice inaccuracies or missing information? Lead the effort to correct and enhance it. <a class="header-anchor" href="#notice-inaccuracies-or-missing-information-lead-the-effort-to-correct-and-enhance-it" aria-label="Permalink to &quot;Notice inaccuracies or missing information? Lead the effort to correct and enhance it.&quot;">​</a></h3><h2 id="share-using-the-forum-for-knowledge-management" tabindex="-1">Share using the <a href="https://forum.irregularchat.com" target="_blank" rel="noreferrer">Forum</a> for Knowledge Management. <a class="header-anchor" href="#share-using-the-forum-for-knowledge-management" aria-label="Permalink to &quot;Share using the [Forum](https://forum.irregularchat.com) for Knowledge Management.&quot;">​</a></h2><p>If you encounter a missing page, take the initiative to create it.</p><h3 id="encounter-a-missing-page-take-the-initiative-to-create-it" tabindex="-1">Encounter a missing page? Take the initiative to create it. <a class="header-anchor" href="#encounter-a-missing-page-take-the-initiative-to-create-it" aria-label="Permalink to &quot;Encounter a missing page? Take the initiative to create it.&quot;">​</a></h3><ul><li>If you suspect spillage, vulnerability, or threat, REPORT it to at least two admins. You can select each chat&#39;s more info option and see who the admins are.</li></ul><h3 id="community-forum" tabindex="-1">Community Forum <a class="header-anchor" href="#community-forum" aria-label="Permalink to &quot;Community Forum&quot;">​</a></h3><p>Using the IrregularChat Login, you can engage with the IrregularChat Forum. You can start <a href="https://forum.irregularchat.com/t/irregularchat-community-faq-guidelines/4" target="_blank" rel="noreferrer">here</a> (Login Required)</p><p>The best way to use the forum is to add links, questions, and content, which will automatically post on the matrix chats. You can then post that link to the signal chat, allowing the community to reference it later.</p><h3 id="history-of-the-irregularchat-community" tabindex="-1">History of the IrregularChat Community <a class="header-anchor" href="#history-of-the-irregularchat-community" aria-label="Permalink to &quot;History of the IrregularChat Community&quot;">​</a></h3><p>In 2021, Trish, the Group S8 at the time, established the Innovation and Evolution Council (IEC) within the 4th PSYOP Group to harness insights directly from the team level for U.S. Army and SOF modernization. This initiative sparked numerous collaborative projects, including forming writing groups and creating the 4th PSYOP Group Operational Skills Detachment (OSD). To enhance OSD’s capabilities, it became necessary to collaborate with experts in Cyber, Special Forces (SF), and Electronic Warfare (EW) from outside the 4th PSYOP Group. Consequently, Trish and Sac started the IrregularChat.</p><p>Originating from the 18 initial members of the IEC, the IrregularChat quickly expanded, attracting Special Operations Forces (SOF) personnel who were independently pursuing innovative projects and sought a community of like-minded professionals. This platform facilitated an unprecedented exchange of ideas and practices across the SOF community.</p><p>[Community] [Required]</p>',30)])])}const f=t(i,[["render",n]]);export{d as __pageData,f as default};
